"""KneeOps remote run exp101:rn34-5fold (private). Generated by tools/remote_bundle_v3.py.

Trains folds 0,1,2,3,4 of artifacts/experiments/EXP101_KFOLD_RN34_PROTOCOL_V1 sequentially on one T4 via tools/remote_run_v3.py; every fold writes /kaggle/working/<tag>/ as it goes.
Success = /kaggle/working/exp101-status.json state COMPLETE plus hash verification after download, not the kernel status.
"""
import glob, os, subprocess, sys, time
t0 = time.time()
print(subprocess.run(["nvidia-smi", "--query-gpu=name,memory.total,driver_version", "--format=csv,noheader"], capture_output=True, text=True).stdout, flush=True)
print("python", sys.version, "| cpus", os.cpu_count(), flush=True)
hits = glob.glob("/kaggle/input/**/tools/remote_run_v3.py", recursive=True)
assert hits, "taeyangg4/knee-runners-v3 dataset not attached"
tools = os.path.dirname(os.path.dirname(hits[0]))
shards = glob.glob("/kaggle/input/**/vols_shard00.npy", recursive=True)
assert shards, "taeyangg4/knee-raptor-corpus-336 dataset not attached"
corpus = os.path.dirname(shards[0])
print("tools", tools, "| corpus", corpus, flush=True)
cmd = [sys.executable, hits[0], "--job", 'exp101:rn34-5fold', "--tools", tools, "--corpus", corpus, "--folds", '0,1,2,3,4', "--results", "/kaggle/working",
       "--budget-hours", "11.0"]
code = subprocess.run(cmd).returncode
print(f"remote_run_v3 exit {code} after {time.time() - t0:.0f}s; see /kaggle/working/exp101-status.json", flush=True)
